  for (const c of [{}, {maxBodyLength:-1}, {maxRedirects:0}]) {
    try { const r = await axios.post(u,'x'.repeat(2e7),c); console.log('OK', r.data); } catch(e){ console.log('ERR', e.message); }
  }
  try { await axios.post(u,'x'.repeat(2e7),{maxBodyLength:1000}); } catch(e){ console.log('ERR expected', e.message); }
  s.close();
});
EOF
